.darma-loader-darma-b16-boot-sector-scan { --accent: var(--loader-color, #22c55e); --accent-2: var(--loader-secondary-color, #84cc16); width: var(--loader-size, 132px); height: calc(var(--loader-size, 132px) * .44); position: relative; }
.darma-loader-darma-b16-boot-sector-scan .darma-loader-darma-b16-boot-sector-scan__grid { position: absolute; left: 0; right: 0; top: 0; height: 72%; display: grid; grid-template-columns: repeat(6, 1fr); grid-auto-rows: 1fr; gap: 4%; }
.darma-loader-darma-b16-boot-sector-scan span { border-radius: 3px; background: color-mix(in srgb, var(--accent) 16%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 35%, transparent); animation: darma-loader-darma-b16-boot-sector-scan-sector-check calc(var(--loader-speed, 1s) * 2.8) steps(1, end) infinite; }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(4) { animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(5) { animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(6) { animation-delay: calc(var(--loader-speed, 1s) * 1); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(7) { animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(8) { animation-delay: calc(var(--loader-speed, 1s) * 1.4); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(9) { animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(10) { animation-delay: calc(var(--loader-speed, 1s) * 1.8); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(11) { animation-delay: calc(var(--loader-speed, 1s) * 2); }
.darma-loader-darma-b16-boot-sector-scan span:nth-of-type(12) { animation-delay: calc(var(--loader-speed, 1s) * 2.2); }
.darma-loader-darma-b16-boot-sector-scan .darma-loader-darma-b16-boot-sector-scan__caret { position: absolute; left: 0; bottom: 2%; width: 8%; height: 16%; background: var(--accent-2); animation: darma-loader-darma-b16-boot-sector-scan-sector-caret calc(var(--loader-speed, 1s) * .8) steps(1, end) infinite; }
@keyframes darma-loader-darma-b16-boot-sector-scan-sector-check { 0%, 6% { background: color-mix(in srgb, var(--accent) 16%, transparent); } 7%, 20% { background: var(--accent-2); } 21%, 100% { background: var(--accent); } }
@keyframes darma-loader-darma-b16-boot-sector-scan-sector-caret { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }

